"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  Activity,
  BarChart3,
  Fish,
  Home,
  Map,
  MoreHorizontal,
  Settings,
  Waves,
} from "lucide-react";
import { useState } from "react";

const NAV = [
  { href: "/", label: "Accueil", icon: Home },
  { href: "/prevision", label: "Prévision", icon: Activity },
  { href: "/carte", label: "Carte", icon: Map },
  { href: "/historique", label: "Historique", icon: BarChart3 },
  { href: "/captures", label: "Captures", icon: Fish },
  { href: "/analyse", label: "Analyse", icon: Waves },
  { href: "/parametres", label: "Paramètres", icon: Settings },
];

const PRIMARY = ["/", "/prevision", "/carte", "/captures"];

export function Shell({ children }: { children: React.ReactNode }) {
  const path = usePathname();
  const [more, setMore] = useState(false);

  return (
    <div className="min-h-screen grid-paper">
      <header className="sticky top-0 z-40 border-b border-white/10 bg-ink-950/85 backdrop-blur-md">
        <div className="mx-auto flex max-w-6xl items-center justify-between gap-3 px-4 py-3">
          <Link href="/" className="flex items-center gap-3">
            <span className="grid h-10 w-10 place-items-center rounded-xl bg-teal/15 text-teal ring-1 ring-teal/40">
              <Fish className="h-5 w-5" />
            </span>
            <span>
              <span className="block font-semibold tracking-wide text-mist-100">PêcheSanguinet</span>
              <span className="block text-xs text-mist-500">Lac de Cazaux-Sanguinet</span>
            </span>
          </Link>
          <nav className="hidden items-center gap-1 lg:flex">
            {NAV.map((item) => {
              const active = path === item.href;
              const Icon = item.icon;
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  className={`flex items-center gap-2 rounded-lg px-3 py-2 text-sm touch-target ${
                    active
                      ? "bg-white/10 text-teal"
                      : "text-mist-300 hover:bg-white/5 hover:text-mist-100"
                  }`}
                >
                  <Icon className="h-4 w-4" />
                  {item.label}
                </Link>
              );
            })}
          </nav>
        </div>
      </header>

      <main className="mx-auto max-w-6xl px-4 pb-28 pt-5 lg:pb-12">{children}</main>

      <nav className="fixed inset-x-0 bottom-0 z-40 border-t border-white/10 bg-ink-950/95 backdrop-blur-md lg:hidden">
        <div className="grid grid-cols-5 px-1 py-1">
          {NAV.filter((n) => PRIMARY.includes(n.href)).map((item) => {
            const Icon = item.icon;
            const active = path === item.href;
            return (
              <Link
                key={item.href}
                href={item.href}
                className={`flex flex-col items-center gap-0.5 py-2 text-[11px] ${
                  active ? "text-teal" : "text-mist-500"
                }`}
              >
                <Icon className="h-5 w-5" />
                {item.label}
              </Link>
            );
          })}
          <button
            type="button"
            onClick={() => setMore((v) => !v)}
            className="flex flex-col items-center gap-0.5 py-2 text-[11px] text-mist-500"
          >
            <MoreHorizontal className="h-5 w-5" />
            Plus
          </button>
        </div>
        {more && (
          <div className="grid grid-cols-3 gap-2 border-t border-white/10 px-3 py-3">
            {NAV.filter((n) => !PRIMARY.includes(n.href)).map((item) => (
              <Link
                key={item.href}
                href={item.href}
                onClick={() => setMore(false)}
                className="rounded-lg bg-ink-800 px-3 py-3 text-center text-sm text-mist-100"
              >
                {item.label}
              </Link>
            ))}
            <Link
              href="/sources"
              onClick={() => setMore(false)}
              className="rounded-lg bg-ink-800 px-3 py-3 text-center text-sm text-mist-100"
            >
              Sources
            </Link>
            <Link
              href="/admin"
              onClick={() => setMore(false)}
              className="rounded-lg bg-ink-800 px-3 py-3 text-center text-sm text-mist-100"
            >
              Admin
            </Link>
          </div>
        )}
      </nav>
    </div>
  );
}

"use client";

import { bestFishingWindows, nowHourIndex } from "@/lib/engines/explain";
import { formatChartTick, formatTime, formatWeekdayHour } from "@/lib/format";
import type { HourlyPoint } from "@/lib/types";
import {
  CartesianGrid,
  Line,
  LineChart,
  ReferenceArea,
  ReferenceLine,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

function fishingDot(props: {
  key?: string;
  index?: number;
  cx?: number;
  cy?: number;
  payload?: { isNow?: boolean; isPeak?: boolean };
}) {
  const key = props.key ?? `dot-${props.index ?? 0}`;
  const { cx, cy, payload } = props;
  if (cx == null || cy == null) return <g key={key} />;
  if (payload?.isNow) {
    return (
      <g key={key}>
        <circle cx={cx} cy={cy} r={8} fill="rgba(232,238,244,0.18)" />
        <circle cx={cx} cy={cy} r={5} fill="#e8eef4" stroke="#2ec4b6" strokeWidth={2} />
      </g>
    );
  }
  if (payload?.isPeak) {
    return (
      <g key={key}>
        <circle cx={cx} cy={cy} r={4.5} fill="#d4a853" stroke="#0b1117" strokeWidth={1.5} />
      </g>
    );
  }
  return <g key={key} />;
}

export function TrendChart({
  points,
  metric = "ifScore",
}: {
  points: HourlyPoint[];
  metric?: "ifScore" | "airTempC" | "waterTempC" | "pressureHpa" | "windKmh" | "cloudPct";
}) {
  const fishing = metric === "ifScore";
  const nowIdx = nowHourIndex(points);
  const windows = fishing ? bestFishingWindows(points) : [];
  const peakIdx = new Set(windows.map((w) => w.peakIdx));

  const data = points.map((p, i) => ({
    i,
    ...p,
    label: formatChartTick(p.time),
    isNow: i === nowIdx,
    isPeak: peakIdx.has(i),
  }));

  const color =
    metric === "ifScore" ? "#2ec4b6" : metric === "pressureHpa" ? "#d4a853" : "#8b9bb0";

  return (
    <div>
      <div className={fishing ? "h-64 w-full" : "h-56 w-full"}>
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={data} margin={{ top: 22, right: 10, left: 0, bottom: 0 }}>
            <CartesianGrid stroke="rgba(255,255,255,0.06)" />
            <XAxis
              dataKey="i"
              type="number"
              domain={[0, Math.max(0, data.length - 1)]}
              ticks={data.map((_, i) => i).filter((i) => i % 6 === 0)}
              tickFormatter={(i) => data[i]?.label ?? ""}
              stroke="#8b9bb0"
              tick={{ fontSize: 11 }}
            />
            <YAxis
              stroke="#8b9bb0"
              tick={{ fontSize: 11 }}
              width={36}
              domain={["auto", "auto"]}
            />
            <Tooltip
              content={({ active, payload }) => {
                if (!active || !payload?.[0]) return null;
                const p = payload[0].payload as (typeof data)[number];
                return (
                  <div className="rounded-lg border border-white/10 bg-ink-800 px-3 py-2 text-xs">
                    <p className="text-mist-300">{formatWeekdayHour(p.time)}</p>
                    <p className="font-mono text-sm text-mist-100">
                      {metric === "ifScore" ? "IF" : metric} {p[metric] ?? "—"}
                    </p>
                    {p.isNow && <p className="mt-1 font-semibold text-mist-100">Maintenant</p>}
                    {p.isPeak && <p className="mt-1 font-semibold text-gold">Meilleure heure</p>}
                  </div>
                );
              }}
            />
            {windows.map((w) => (
              <ReferenceArea
                key={`${w.from}-${w.to}`}
                x1={w.startIdx === w.endIdx ? w.startIdx - 0.45 : w.startIdx}
                x2={w.startIdx === w.endIdx ? w.endIdx + 0.45 : w.endIdx}
                fill="#d4a853"
                fillOpacity={0.16}
                ifOverflow="extendDomain"
              />
            ))}
            {fishing && (
              <ReferenceLine
                x={nowIdx}
                stroke="#e8eef4"
                strokeWidth={1.5}
                strokeDasharray="4 4"
                label={{
                  value: "Maintenant",
                  position: nowIdx < 8 ? "insideTopLeft" : "top",
                  fill: "#e8eef4",
                  fontSize: 11,
                  fontWeight: 600,
                }}
              />
            )}
            <Line
              type="monotone"
              dataKey={metric}
              stroke={color}
              strokeWidth={2}
              dot={fishing ? fishingDot : false}
              activeDot={{ r: 5 }}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>
      {fishing && (
        <div className="mt-3 flex flex-wrap items-center gap-2 text-xs">
          <span className="inline-flex items-center gap-1.5 rounded-full border border-white/15 bg-white/5 px-2.5 py-1 text-mist-100">
            <span className="h-2.5 w-2.5 rounded-full bg-mist-100 ring-2 ring-teal" />
            Maintenant · {formatTime(points[nowIdx]?.time)}
          </span>
          {windows.length === 0 && (
            <span className="text-mist-500">Pas de pic nettement plus favorable sur 72 h.</span>
          )}
          {windows.map((w) => (
            <span
              key={w.peakTime}
              className="inline-flex items-center gap-1.5 rounded-full border border-gold/40 bg-gold/10 px-2.5 py-1 text-gold"
            >
              <span className="h-2.5 w-2.5 rounded-full bg-gold" />
              {formatTime(w.from)}
              {w.from !== w.to ? `–${formatTime(w.to)}` : ""} · pic {w.peak}
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

import { levelLabel } from "@/lib/format";
import type { FrenzyLevel } from "@/lib/types";

export function Panel({
  children,
  className = "",
}: {
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <section className={`rounded-2xl border border-white/10 bg-ink-800/80 p-4 shadow-panel ${className}`}>
      {children}
    </section>
  );
}

export function Label({ children }: { children: React.ReactNode }) {
  return (
    <p className="text-[11px] font-semibold uppercase tracking-[0.18em] text-mist-500">{children}</p>
  );
}

export function scoreColor(score: number | null): string {
  if (score == null) return "text-mist-500";
  if (score >= 76) return "text-signal-good";
  if (score >= 61) return "text-teal";
  if (score >= 41) return "text-signal-mid";
  return "text-signal-bad";
}

export function scoreBg(score: number | null): string {
  if (score == null) return "bg-white/5";
  if (score >= 76) return "bg-signal-good/15";
  if (score >= 61) return "bg-teal/15";
  if (score >= 41) return "bg-signal-mid/15";
  return "bg-signal-bad/15";
}

export function LevelBadge({ level }: { level: FrenzyLevel | null }) {
  if (!level) return <span className="text-mist-500">Indice indisponible</span>;
  return <span className="font-semibold tracking-widest">{levelLabel(level)}</span>;
}

export function Stamp({ text }: { text: string }) {
  return <p className="text-xs text-mist-500">{text}</p>;
}

export function KindTag({ kind }: { kind: string }) {
  return (
    <span className="rounded-md border border-gold/40 bg-gold/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-gold">
      {kind}
    </span>
  );
}

import type { SnapshotOk } from "@/lib/services/snapshot";
import { Label, Panel } from "./ui";

export function WhyPanel({ snap }: { snap: SnapshotOk }) {
  const impact = [...snap.if.factors].sort((a, b) => b.points - a.points)[0];
  return (
    <Panel>
      <Label>Pourquoi ?</Label>
      <ul className="mt-3 space-y-2 text-sm leading-relaxed text-mist-300">
        {snap.if.why.map((line) => (
          <li key={line} className="border-l-2 border-teal/40 pl-3">
            {line}
          </li>
        ))}
      </ul>
      {impact && (
        <p className="mt-4 text-xs text-mist-500">
          Plus fort impact sur le total : {impact.label} (+{impact.points} / {impact.maxPoints})
        </p>
      )}
      <div className="mt-4 space-y-2 font-mono text-sm tabular">
        {snap.if.factors.map((f) => (
          <div key={f.id} className="flex items-center justify-between gap-3">
            <span className="text-mist-500">{f.label}</span>
            <span className={f.available ? "text-mist-100" : "text-signal-mid"}>
              {f.available ? `+${f.points}` : "indisponible"}
            </span>
          </div>
        ))}
        <div className="flex justify-between border-t border-white/10 pt-2 font-semibold">
          <span>TOTAL</span>
          <span>{snap.if.score ?? "—"}</span>
        </div>
      </div>
    </Panel>
  );
}

import { promises as fs } from "fs";
import path from "path";
import { dataPath, readJson, writeJson } from "./store/jsonStore";
import { getConfig } from "./config";

interface CacheEnvelope<T> {
  fetchedAt: string;
  source: string;
  payload: T;
}

export async function getCached<T>(key: string): Promise<CacheEnvelope<T> | null> {
  return readJson<CacheEnvelope<T>>(`cache/${key}.json`);
}

export async function setCached<T>(
  key: string,
  source: string,
  payload: T,
): Promise<CacheEnvelope<T>> {
  const envelope: CacheEnvelope<T> = {
    fetchedAt: new Date().toISOString(),
    source,
    payload,
  };
  await writeJson(`cache/${key}.json`, envelope);
  return envelope;
}

export function isFresh(fetchedAt: string, ttlMinutes: number): boolean {
  const age = Date.now() - new Date(fetchedAt).getTime();
  return age < ttlMinutes * 60_000;
}

export async function cachedFetch<T>(opts: {
  key: string;
  source: string;
  ttlMinutes?: number;
  loader: () => Promise<T>;
}): Promise<{ data: T; fetchedAt: string; fromCache: boolean; stale: boolean; source: string }> {
  const cfg = await getConfig();
  const ttl = opts.ttlMinutes ?? cfg.cacheTtlMinutes;
  const existing = await getCached<T>(opts.key);

  if (existing && isFresh(existing.fetchedAt, ttl)) {
    return {
      data: existing.payload,
      fetchedAt: existing.fetchedAt,
      fromCache: true,
      stale: false,
      source: existing.source,
    };
  }

  try {
    const payload = await opts.loader();
    const saved = await setCached(opts.key, opts.source, payload);
    return {
      data: payload,
      fetchedAt: saved.fetchedAt,
      fromCache: false,
      stale: false,
      source: opts.source,
    };
  } catch (err) {
    if (existing) {
      return {
        data: existing.payload,
        fetchedAt: existing.fetchedAt,
        fromCache: true,
        stale: true,
        source: existing.source,
      };
    }
    throw err;
  }
}

export async function clearWeatherCache(): Promise<number> {
  const dir = dataPath("cache");
  try {
    const files = await fs.readdir(dir);
    await Promise.all(files.map((f) => fs.unlink(path.join(dir, f))));
    return files.length;
  } catch {
    return 0;
  }
}

import type { AppConfig } from "./types";
import { readJson, writeJson } from "./store/jsonStore";

export const DEFAULT_CONFIG: AppConfig = {
  weights: {
    water: 0.3,
    pressure: 0.2,
    wind: 0.2,
    cloud: 0.15,
    historical: 0.15,
  },
  levels: {
    tresMauvais: 0,
    faible: 21,
    moyen: 41,
    bon: 61,
    tresBon: 76,
    exceptionnel: 91,
  },
  cacheTtlMinutes: 20,
  sectorId: "sanguinet",
  anglerName: "",
  notifications: false,
};

export async function getConfig(): Promise<AppConfig> {
  const stored = await readJson<AppConfig>("config.json");
  if (!stored) return DEFAULT_CONFIG;
  return {
    weights: { ...DEFAULT_CONFIG.weights, ...stored.weights },
    levels: { ...DEFAULT_CONFIG.levels, ...stored.levels },
    cacheTtlMinutes: stored.cacheTtlMinutes ?? DEFAULT_CONFIG.cacheTtlMinutes,
    sectorId: stored.sectorId ?? DEFAULT_CONFIG.sectorId,
    anglerName: stored.anglerName ?? "",
    notifications: stored.notifications ?? false,
  };
}

export async function saveConfig(next: AppConfig): Promise<void> {
  const sum =
    next.weights.water +
    next.weights.pressure +
    next.weights.wind +
    next.weights.cloud +
    next.weights.historical;
  if (sum <= 0) throw new Error("Les pondérations doivent être > 0");
  await writeJson("config.json", next);
}

import type { FishingAlert } from "../types";
import { formatTime } from "../format";
import { pressureDeltas, type PressureSeries } from "./pressure";

export function buildAlerts(opts: {
  ifNow: number | null;
  confidence: number;
  window: { from: string; to: string; peak: number } | null;
  pressure: PressureSeries;
  windNow: number | null;
  windPlus6: number | null;
  waterDelta24: number | null;
}): FishingAlert[] {
  const alerts: FishingAlert[] = [];

  if (opts.window && opts.window.peak >= 76) {
    alerts.push({
      id: "fenetre",
      kind: "fenetre",
      title: "Fenêtre favorable détectée",
      body: `${formatTime(opts.window.from)} → ${formatTime(opts.window.to)} · IF prévu ${opts.window.peak} · confiance ${opts.confidence} %`,
    });
  }

  const d = pressureDeltas(opts.pressure);
  if (d.d12 != null && d.d12 <= -4) {
    alerts.push({
      id: "pression",
      kind: "pression",
      title: "Chute de pression",
      body: `${d.d12.toFixed(1)} hPa en 12 h. Le modèle V1 traite une baisse progressive comme un signal, une chute brutale comme un régime instable.`,
    });
  }

  if (opts.windNow != null && opts.windPlus6 != null && Math.abs(opts.windPlus6 - opts.windNow) >= 15) {
    alerts.push({
      id: "vent",
      kind: "vent",
      title: "Changement de vent prévu",
      body: `Passage de ${Math.round(opts.windNow)} à ${Math.round(opts.windPlus6)} km/h d'ici 6 h.`,
    });
  }

  if (opts.waterDelta24 != null && Math.abs(opts.waterDelta24) >= 1.8) {
    alerts.push({
      id: "temperature",
      kind: "temperature",
      title: "Variation thermique de l'eau",
      body: `${opts.waterDelta24 > 0 ? "+" : ""}${opts.waterDelta24.toFixed(1)} °C estimés sur 24 h.`,
    });
  }

  if (opts.ifNow != null && opts.ifNow >= 91) {
    alerts.push({
      id: "exceptionnel",
      kind: "exceptionnel",
      title: "Conditions exceptionnelles (modèle)",
      body: `IF ${opts.ifNow}/100. Ce n'est pas une garantie de capture — uniquement un alignement des facteurs environnementaux V1.`,
    });
  }

  return alerts;
}

import { clamp } from "../format";

export function scoreCloud(opts: {
  cloudPct: number | null;
  hour?: number | null;
  precipMm?: number | null;
}): { score: number; detail: string; available: boolean } {
  if (opts.cloudPct == null) {
    return { score: 0, detail: "Donnée indisponible", available: false };
  }
  const c = opts.cloudPct;
  let score: number;
  if (c >= 60 && c <= 90) score = 92;
  else if (c > 90) score = 80;
  else if (c >= 40) score = 74;
  else if (c >= 20) score = 52;
  else score = 34;

  if (opts.precipMm != null && opts.precipMm > 2) score -= 10;
  if (opts.precipMm != null && opts.precipMm > 6) score -= 10;

  if (opts.hour != null && (opts.hour <= 8 || opts.hour >= 18)) score += 6;

  return {
    score: clamp(Math.round(score), 0, 100),
    detail: `${Math.round(c)} % de nébulosité${opts.precipMm && opts.precipMm > 0.2 ? `, ${opts.precipMm.toFixed(1)} mm` : ""}`,
    available: true,
  };
}

import type { FactorScore } from "../types";
import { pressureTrendLabel } from "./pressure";

export function explainScore(opts: {
  total: number | null;
  factors: FactorScore[];
  waterNote?: string;
  pressureDelta12?: number | null;
  windText?: string;
  analogCount: number;
  catchRate: number | null;
  confidence: number;
}): string[] {
  const lines: string[] = [];
  if (opts.total == null) {
    lines.push("Impossible de calculer l'indice : trop de données manquantes.");
    return lines;
  }

  if (opts.total >= 76) lines.push("Conditions environnementales actuellement favorables selon le modèle V1.");
  else if (opts.total >= 61) lines.push("Conditions globalement correctes, sans régime exceptionnel.");
  else if (opts.total >= 41) lines.push("Conditions mixtes : certains facteurs aident, d'autres limitent.");
  else lines.push("Conditions peu favorables au modèle actuel.");

  const ranked = [...opts.factors].filter((f) => f.available).sort((a, b) => b.rawScore - a.rawScore);
  const best = ranked[0];
  const worst = ranked[ranked.length - 1];
  if (best) lines.push(`Facteur le plus porteur : ${best.label.toLowerCase()} (${best.detail}).`);
  if (worst && worst.id !== best?.id) {
    lines.push(`Facteur le plus limitant : ${worst.label.toLowerCase()} (${worst.detail}).`);
  }

  if (opts.waterNote) lines.push(opts.waterNote);
  if (opts.pressureDelta12 != null) {
    lines.push(`Pression ${pressureTrendLabel(opts.pressureDelta12)} sur 12 h.`);
  }
  if (opts.windText) lines.push(opts.windText);

  lines.push(
    `${opts.analogCount} journée${opts.analogCount > 1 ? "s" : ""} historique${opts.analogCount > 1 ? "s" : ""} à conditions météo comparables.`,
  );

  if (opts.catchRate == null) {
    lines.push(
      "Pas de statistique de capture : le journal local est insuffisant. Il s'agit de similarité météorologique, pas d'une probabilité de prendre un poisson.",
    );
  } else {
    lines.push(
      `Parmi les analogues avec captures enregistrées, ${opts.catchRate} % des journées ont au moins une prise (échantillon encore limité).`,
    );
  }

  if (opts.confidence < 60) {
    lines.push(
      `Confiance ${opts.confidence} % : le score environnemental peut être élevé ou bas, mais la prédiction reste fragile.`,
    );
  }

  return lines;
}

export function bestWindow(hourly: { time: string; ifScore: number | null }[]): {
  from: string;
  to: string;
  peak: number;
} | null {
  const scored = hourly.filter((h): h is { time: string; ifScore: number } => h.ifScore != null);
  if (scored.length < 3) return null;
  let bestStart = 0;
  let bestSum = -1;
  const w = 3;
  for (let i = 0; i <= scored.length - w; i++) {
    const sum = scored[i].ifScore + scored[i + 1].ifScore + scored[i + 2].ifScore;
    if (sum > bestSum) {
      bestSum = sum;
      bestStart = i;
    }
  }
  const slice = scored.slice(bestStart, bestStart + w);
  return {
    from: slice[0].time,
    to: slice[slice.length - 1].time,
    peak: Math.max(...slice.map((s) => s.ifScore)),
  };
}

export interface FishingWindow {
  from: string;
  to: string;
  peak: number;
  peakTime: string;
  startIdx: number;
  endIdx: number;
  peakIdx: number;
}

export function nowHourIndex(hourly: { time: string }[], at = Date.now()): number {
  if (!hourly.length) return 0;
  let best = 0;
  let bestD = Infinity;
  for (let i = 0; i < hourly.length; i++) {
    const d = Math.abs(new Date(hourly[i].time).getTime() - at);
    if (d < bestD) {
      bestD = d;
      best = i;
    }
  }
  return best;
}

/** Pics locaux — pas toute une journée au-dessus de 76. */
export function bestFishingWindows(
  hourly: { time: string; ifScore: number | null }[],
  maxWindows = 3,
): FishingWindow[] {
  const scored = hourly
    .map((h, i) => ({ i, time: h.time, ifScore: h.ifScore }))
    .filter((h): h is { i: number; time: string; ifScore: number } => h.ifScore != null);
  if (scored.length < 3) return [];

  const max = Math.max(...scored.map((s) => s.ifScore));
  const peakLocs: number[] = [];
  for (let k = 1; k < scored.length - 1; k++) {
    const p = scored[k].ifScore;
    if (p >= scored[k - 1].ifScore && p > scored[k + 1].ifScore) peakLocs.push(k);
  }
  if (!peakLocs.length) {
    const hi = scored.reduce((b, s, k) => (s.ifScore > scored[b].ifScore ? k : b), 0);
    peakLocs.push(hi);
  }

  const kept = peakLocs
    .filter((k) => scored[k].ifScore >= max - 4)
    .sort((a, b) => scored[b].ifScore - scored[a].ifScore || a - b)
    .slice(0, maxWindows)
    .sort((a, b) => a - b);

  const windows: FishingWindow[] = [];
  for (const pk of kept) {
    const peakScore = scored[pk].ifScore;
    let L = pk;
    let R = pk;
    while (
      L > 0 &&
      scored[L - 1].ifScore >= peakScore - 4 &&
      scored[L - 1].ifScore >= 61 &&
      pk - (L - 1) < 3
    ) {
      L -= 1;
    }
    while (
      R < scored.length - 1 &&
      scored[R + 1].ifScore >= peakScore - 4 &&
      scored[R + 1].ifScore >= 61 &&
      R + 1 - pk < 3
    ) {
      R += 1;
    }
    if (windows.some((w) => !(scored[R].i < w.startIdx || scored[L].i > w.endIdx))) continue;
    windows.push({
      from: scored[L].time,
      to: scored[R].time,
      peak: peakScore,
      peakTime: scored[pk].time,
      startIdx: scored[L].i,
      endIdx: scored[R].i,
      peakIdx: scored[pk].i,
    });
  }
  return windows.sort((a, b) => a.startIdx - b.startIdx);
}

import type {
  FactorScore,
  FrenzyLevel,
  LevelThresholds,
  ModelWeights,
  SpeciesId,
} from "../types";
import { clamp } from "../format";
import { scoreWater } from "./water";
import { scorePressure, type PressureSeries } from "./pressure";
import { scoreWind } from "./wind";
import { scoreCloud } from "./cloud";

export function levelFromScore(score: number, levels: LevelThresholds): FrenzyLevel {
  if (score >= levels.exceptionnel) return "EXCEPTIONNEL";
  if (score >= levels.tresBon) return "TRES_BON";
  if (score >= levels.bon) return "BON";
  if (score >= levels.moyen) return "MOYEN";
  if (score >= levels.faible) return "FAIBLE";
  return "TRES_MAUVAIS";
}

export function normalizeWeights(w: ModelWeights, available: Record<keyof ModelWeights, boolean>): ModelWeights {
  const keys = Object.keys(w) as (keyof ModelWeights)[];
  const raw: ModelWeights = { ...w };
  for (const k of keys) {
    if (!available[k]) raw[k] = 0;
  }
  const sum = keys.reduce((a, k) => a + raw[k], 0);
  if (sum <= 0) return { water: 0, pressure: 0, wind: 0, cloud: 0, historical: 0 };
  const out = { ...raw };
  for (const k of keys) out[k] = raw[k] / sum;
  return out;
}

export interface EngineInput {
  waterTempC: number | null;
  waterDelta6h?: number | null;
  waterDelta24h?: number | null;
  pressure: PressureSeries;
  windKmh: number | null;
  gustKmh?: number | null;
  cloudPct: number | null;
  precipMm?: number | null;
  hour?: number | null;
  historicalScore: number | null;
  historicalDetail: string;
  weights: ModelWeights;
}

export function computeFrenzy(input: EngineInput): {
  total: number | null;
  factors: FactorScore[];
  usedWeights: ModelWeights;
} {
  const water = scoreWater({
    tempC: input.waterTempC,
    delta6h: input.waterDelta6h,
    delta24h: input.waterDelta24h,
  });
  const pressure = scorePressure(input.pressure);
  const wind = scoreWind({ speedKmh: input.windKmh, gustKmh: input.gustKmh });
  const cloud = scoreCloud({
    cloudPct: input.cloudPct,
    hour: input.hour,
    precipMm: input.precipMm,
  });
  const historicalAvailable = input.historicalScore != null;
  const historical = {
    score: input.historicalScore ?? 0,
    detail: input.historicalDetail,
    available: historicalAvailable,
  };

  const available = {
    water: water.available,
    pressure: pressure.available,
    wind: wind.available,
    cloud: cloud.available,
    historical: historical.available,
  };

  const used = normalizeWeights(input.weights, available);
  const parts: { id: keyof ModelWeights; label: string; result: typeof water }[] = [
    { id: "water", label: "Température eau", result: water },
    { id: "pressure", label: "Pression", result: pressure },
    { id: "wind", label: "Vent", result: wind },
    { id: "cloud", label: "Nébulosité", result: cloud },
    { id: "historical", label: "Historique", result: historical },
  ];

  const factors: FactorScore[] = parts.map((p) => {
    const maxPoints = Math.round(used[p.id] * 100);
    const points = p.result.available ? Math.round((p.result.score / 100) * maxPoints) : 0;
    return {
      id: p.id,
      label: p.label,
      points,
      maxPoints,
      rawScore: p.result.score,
      available: p.result.available,
      detail: p.result.detail,
    };
  });

  const any = factors.some((f) => f.available);
  const total = any ? clamp(factors.reduce((a, f) => a + f.points, 0), 0, 100) : null;

  return { total, factors, usedWeights: used };
}

